 82 function getCanonicalName(model: string): string {
 83   // "anthropic/claude-opus-4-6" → "claude-opus-4-6"
 84   const slashIdx = model.lastIndexOf("/");
 85   const base = slashIdx >= 0 ? model.slice(slashIdx + 1) : model;
 86   // Strip date suffixes like "-20250301"
 87   return base.replace(/-\d{8}$/, "");
